def fill_streets(apps, schema_editor):
    """Give every existing plot its street, from its number."""
    Plot = apps.get_model('core', 'Plot')
    for plot in Plot.objects.filter(street=''):
        if not plot.number.strip().isdigit():
            continue
        n = int(plot.number)
        street = next((s for first, last, s in PLOT_STREETS if first <= n <= last), '')
        if street:
            plot.street = street
            plot.save(update_fields=['street'])


